import unittest
from candidate import strange_sort_list

class TestStrangeSortList(unittest.TestCase):
    def test_normal_case_odd_length(self):
        self.assertEqual(strange_sort_list([1, 2, 3, 4, 5]), [1, 5, 2, 4, 3])

    def test_normal_case_even_length(self):
        self.assertEqual(strange_sort_list([1, 2, 3, 4]), [1, 4, 2, 3])

    def test_all_identical_elements(self):
        self.assertEqual(strange_sort_list([5, 5, 5, 5]), [5, 5, 5, 5])

    def test_empty_list(self):
        self.assertEqual(strange_sort_list([]), [])

    def test_single_element(self):
        self.assertEqual(strange_sort_list([42]), [42])

    def test_negative_numbers(self):
        self.assertEqual(strange_sort_list([-3, -1, -2, -4]), [-4, -1, -3, -2])

    def test_mixed_positive_negative(self):
        self.assertEqual(strange_sort_list([-1, 2, -3, 4]), [-3, 4, -1, 2])

    def test_duplicates(self):
        self.assertEqual(strange_sort_list([2, 2, 3, 1, 1]), [1, 3, 1, 2, 2])

    def test_boundary_minimum(self):
        self.assertEqual(strange_sort_list([-1000000, -2, -3]), [-1000000, -2, -3])

    def test_boundary_maximum(self):
        self.assertEqual(strange_sort_list([1000000, 2, 3]), [2, 1000000, 3])

    def test_non_integer_elements(self):
        with self.assertRaises(TypeError):
            strange_sort_list([1, 'a', 3])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            strange_sort_list(None)

    def test_list_with_non_integer_elements(self):
        with self.assertRaises(TypeError):
            strange_sort_list([1, 'a', 3])

    def test_large_list(self):
        test_list = list(range(1, 1001))
        expected = []
        remaining = test_list.copy()
        switch = True
        for i in range(len(test_list)):
            if switch:
                expected.append(min(remaining))
            else:
                expected.append(max(remaining))
            remaining.remove(expected[-1])
            switch = not switch
        self.assertEqual(strange_sort_list(test_list), expected)

if __name__ == '__main__':
    unittest.main()
